code='''from collections import deque

def _blocks(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==3 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    r,c=q.popleft(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==3 and not seen[nr][nc]:
                            seen[nr][nc]=True; q.append((nr,nc))
                comps.append(cells)
    return comps

def transform(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    boxes=[(min(r for r,c in cp),max(r for r,c in cp),min(c for r,c in cp),max(c for r,c in cp)) for cp in _blocks(g)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and any(r0<=i<=r1 and c0<=j<=c1 for r0,r1,c0,c1 in boxes):
                for di in(-1,0,1):
                    for dj in(-1,0,1):
                        if di==0 and dj==0: continue
                        r,c=i+di,j+dj
                        if 0<=r<h and 0<=c<w and g[r][c]!=2: o[r][c]=1
    return o
'''
